INSERT INTO `noticia` (`noticia_id`, `noticia_title`, `noticia_foto`, `noticia_content`, `noticia_data`) VALUES
(5, '2º Festa da Espuma Studio 1250', '2deed779fc42258b712268b40eef553c.jpg', '<p><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">&#128166;&#127882; &#128166;&#127882; &#128166;&#127882; &#128166;&#127882; </span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">Venha se refrescar com a gente e curitr muito Flashback</span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">anos 80 e 90  &#128378; &#127899; &#127911; &#127926; </span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">com DJ Julio Reis e convidados.</span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"></p>\r\n\r\n\r\n<ul>\r\n\r\n	<li><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"> fem 10.00 Masc 20.00</span></li></ul>\r\n\r\n<p><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">&#128197; dia 06/04/2019 a partir das &#128346; 23:00hs</span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">&#128205; Av Marechal Mascarenhas de Moraes, 901 - Atuba</span><br style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\">&#9742; 3257-1250</span></p>\r\n\r\n<p><span style=\"color: rgb(29, 33, 41); white-space: pre-wrap;\"><span rel=\"pastemarkerend\" id=\"pastemarkerend85050\"></span></span></p>\r\n<p style=\"text-align: left;\"><br>\r\n\r\n</p>\r\n\r\n', '04/04/2019'),
(6, 'Studio 1250 RAP', '85b1d55a53ba3e358df2f0802bd682b4.jpg', '<p style=\"margin: 0px 0px 6px; color: rgb(29, 33, 41); text-transform: none; text-indent: 0px; letter-spacing: normal; font-family: Helvetica, Arial, sans-serif; font-size: 14px; font-style: normal; font-weight: 400; word-spacing: 0px; display: block; white-space: normal; orphans: 2; widows: 2; background-color: rgb(255, 255, 255); font-variant-ligatures: normal; font-variant-caps: normal; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial;\"><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/t2b/1/16/1f399.png?_nc_eui2=AeFIcm0U5wpS1DQ8gA6Qm-q5l8ddYU_-CMCTRqAVmvoYU13E53ECOdZAt2_S_j-MMBXaQYz0GL7_QAwFgq0hxpD7lj0WeZqClAXwWyybqVeIWg\"); background-repeat: no-repeat; background-size: contain;\'>&#127897;</span></span> *El Clã Records*<span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/t2b/1/16/1f399.png?_nc_eui2=AeFIcm0U5wpS1DQ8gA6Qm-q5l8ddYU_-CMCTRqAVmvoYU13E53ECOdZAt2_S_j-MMBXaQYz0GL7_QAwFgq0hxpD7lj0WeZqClAXwWyybqVeIWg\"); background-repeat: no-repeat; background-size: contain;\'>&#127897;</span></span> em parceria com Studio 1250, apresenta<span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/t5d/1/16/26a1.png?_nc_eui2=AeEEQzhf9nDVYmDfS4qBFX4bGBJQt2ZqevbSbfF5bsFil94wgUXbXJy5f9zvzGoeuOsmj5FMM6HqUgnLhzRc-5kQq5voQU4ybglC-36uN8vEaQ\"); background-repeat: no-repeat; background-size: contain;\'>&#9889;</span></span><br>\r\n- *MIL250RAP* -</p>\r\n<p style=\"margin: 6px 0px; color: rgb(29, 33, 41); text-transform: none; text-indent: 0px; letter-spacing: normal; font-family: Helvetica, Arial, sans-serif; font-size: 14px; font-style: normal; font-weight: 400; word-spacing: 0px; display: block; white-space: normal; orphans: 2; widows: 2; background-color: rgb(255, 255, 255); font-variant-ligatures: normal; font-variant-caps: normal; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial;\">Dia _*14/04*_ Curitiba vai pegar preço com essa grande festa de *HIP HOP* recordando as melhores músicas clássicas do nosso *RAP NACIONAL* com o monstro *@DjMco* comandando as pick up na estrutura monstra da *Studio 1250* & também com a presença dos nossos irmãos *Mc\'s* representantes do rap de Curitiba e região trazendo a vocês essa line foda pra mostrar a cara da nossa cena!</p>\r\n<div class=\"text_exposed_show\" style=\"color: rgb(29, 33, 41); text-transform: none; text-indent: 0px; letter-spacing: normal; font-family: Helvetica, Arial, sans-serif; font-size: 14px; font-style: normal; font-weight: 400; word-spacing: 0px; display: inline; white-space: normal; orphans: 2; widows: 2; background-color: rgb(255, 255, 255); font-variant-ligatures: normal; font-variant-caps: normal; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial;\"><p style=\"margin: 0px 0px 6px; font-family: inherit;\">E mais....</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">*BREAK*</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">*FINAL DA BATALHA DO BACACHERI COM MC\'S FINALISTAS<span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/t50/1/16/1f525.png?_nc_eui2=AeFq0qSzyXO2al4cXeeQ7gGNEpHQCDSfymFo4MDFIf7BCS9bSfn32PUPq6VnjhzSy-bnxPO3UBRvk9PyTAUZqj5FiCs3zDwzT7Jy5jeILtIvgA\"); background-repeat: no-repeat; background-size: contain;\'>&#128293;</span></span>*</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">*FLIPERAMAS* <span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/t5a/1/16/1f47e.png?_nc_eui2=AeG1Ie8ixEJRZGUMpi1bkaZVO0NFF4_ECH0qXh5rP7ijZt-3L82Vj-kwRGKC0kux0gXk2uyaFZjHN4qiyHuz9kk-rgaEhBMEx8bEa9ITyep_pw\"); background-repeat: no-repeat; background-size: contain;\'>&#128126;</span></span></p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">*SORTEIO DE UMA TATTOO ESCRITA NO VALOR DE 250$, E MAIS!*</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">A partir das *14horas*</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\"><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span>+ 16 <span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span><span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/tdc/1/16/26a0.png?_nc_eui2=AeHPWHuHxzwp-Fa-Jw6ZwbgtM-SPSJwNfaYrWNacQQHbgnSJYnRvvSs7TKTJlP3oOA9MlrS2oOJeNJtPcu74PTbwy0XtlFVoN90dxvTwD4OH-Q\"); background-repeat: no-repeat; background-size: contain;\'>&#9888;</span></span><br>\r\n*R$5,00 com nome na lista!*<br>\r\n*R$10,00 na hora sem nome na lista!*<br>\r\nContato<span class=\"_5mfr\" style=\"margin: 0px 1px; font-family: inherit;\"><span class=\"_6qdm\" style=\'width: 16px; height: 16px; color: transparent; font-family: inherit; font-size: 16px; text-decoration: none; vertical-align: text-bottom; display: inline-block; text-shadow: none; background-image: url(\"https://static.xx.fbcdn.net/images/emoji.php/v9/td8/1/16/1f4f2.png?_nc_eui2=AeHBqO5HyjPzqjRK_jrX-r72QWIZj_5sgOo9lNgzshIcO316NmhVRkZe1juVwQixpXfBjqsq4eR5vi1YfAVF_LHIOQiluIhUy4Nx4tO6TURONw\"); background-repeat: no-repeat; background-size: contain;\'>&#128242;</span></span> <br>\r\n999423463<br>\r\n998567551<br>\r\n996260883</p>\r\n<p style=\"margin: 6px 0px; font-family: inherit;\">*Eai vai perder!?*</p>\r\n</div>', '06/04/2019'),
